// Compact each email (Gmail Trigger with Simplify off) and cut quoted history so the AI reads only the new message
const s = $('Set your labels and context').first().json;
const max = Number(s.max_body_chars) || 4000;
return $('Check Gmail for new emails').all().map(({ json: m }) => {
  const from = (m.from && m.from.value && m.from.value[0]) || {};
  let body = String(m.text || m.snippet || '');
  body = body.split(/\r?\n/).filter(l => !l.trim().startsWith('>')).join('\n');
  body = body.replace(/\n\s*On [^\n]{5,200}wrote:[\s\S]*$/, '');
  body = body.replace(/\n{3,}/g, '\n\n').trim().slice(0, max);
  const headers = m.headers || {};
  return { json: {
    message_id: m.id, thread_id: m.threadId,
    from_name: from.name || '', from_email: String(from.address || '').toLowerCase(),
    subject: m.subject || '(no subject)', date: m.date || '',
    has_unsubscribe_link: Boolean(headers['list-unsubscribe']),
    body,
  } };
});

// Map each AI category (and high priority) to the ID of a Gmail label you created, e.g. "AI/Needs reply"
const s = $('Set your labels and context').first().json;
const prefix = s.label_prefix || 'AI/';
const NAMES = { needs_reply: 'Needs reply', action: 'Action', fyi: 'FYI', newsletter: 'Newsletter', receipt: 'Receipt', promotion: 'Promotion' };
const ids = {};
for (const l of $input.all()) ids[String(l.json.name || '').toLowerCase()] = l.json.id;
const emails = $('Clean email text').all();
return $('Classify email with AI').all().map((item, i) => {
  const ai = item.json.output || {};
  const { body, ...e } = emails[i].json;
  const wanted = [prefix + (NAMES[ai.category] || 'FYI')];
  if (ai.priority === 'high') wanted.push(prefix + 'High priority');
  return { json: { ...e, category: ai.category || 'fyi', priority: ai.priority || 'low', summary: ai.summary || '',
    label_ids: wanted.map(n => ids[n.toLowerCase()]).filter(Boolean),
    missing_labels: wanted.filter(n => !ids[n.toLowerCase()]) } };
});
